/**
 * BooKi - Dashboard page (Command Center, 2026-09-10).
 *
 * "Bugünün Akışı" and the KPI row are server-rendered (see Dashboard.php /
 * pages/dashboard.php - real numbers on first paint, no flash of empty
 * state). "Canlı Seanslar" and the "gecikmiş seans" part of "Dikkat
 * Gerektirenler" are populated here, reusing the exact same
 * calendar/get_active_sessions endpoint + App.Utils.SessionStatus helpers
 * the calendar's own active-sessions widget already relies on - so a
 * session's status here always agrees with what the calendar shows.
 */
(function () {
    'use strict';

    const POLL_INTERVAL_MS = 30000;

    function escapeHtml(value) {
        return String(value ?? '').replace(/[&<>"']/g, (c) => ({
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#39;',
        })[c]);
    }

    function statusBadgeClass(status) {
        return (
            {
                overdue: 'kcc-status-amber',
                ending_soon: 'kcc-status-amber',
                running: 'kcc-status-green',
                late_start: 'kcc-status-gray',
                pending: 'kcc-status-gray',
            }[status] || 'kcc-status-gray'
        );
    }

    function customerName(appointment) {
        return [appointment.customer?.first_name, appointment.customer?.last_name].filter(Boolean).join(' ') || 'Müşteri';
    }

    function providerName(appointment) {
        return [appointment.provider?.first_name, appointment.provider?.last_name].filter(Boolean).join(' ');
    }

    function renderLiveSessions(appointments) {
        const $list = $('#dash-live-sessions');
        $('#dash-active-count').text(appointments.length);
        $('#dash-live-count-label').text(appointments.length + ' aktif');

        if (!appointments.length) {
            $list.html('<div class="list-group-item text-muted small py-4 text-center">Şu anda aktif seans yok.</div>');
            return;
        }

        const rows = appointments.map((appointment) => {
            const info = App.Utils.SessionStatus.compute(appointment);
            const duration = Number(appointment.custom_duration_minutes) || Number(appointment.service?.duration) || 1;
            const elapsed = info.remainingMinutes !== null ? Math.max(duration - info.remainingMinutes, 0) : duration;
            const pct = Math.min(Math.round((elapsed / duration) * 100), 100);
            const overdue = info.status === 'overdue';
            const timerLabel =
                info.remainingMinutes === null
                    ? '—'
                    : overdue
                      ? '+' + String(Math.abs(info.remainingMinutes)).padStart(2, '0') + ':00'
                      : Math.floor(info.remainingMinutes) + ' dk kaldı';

            return `
                <div class="list-group-item py-3">
                    <div class="d-flex justify-content-between align-items-start">
                        <strong class="small">${escapeHtml(customerName(appointment))}</strong>
                        <span class="badge ${statusBadgeClass(info.status)}">${escapeHtml(App.Utils.SessionStatus.statusLabel(info.status))}</span>
                    </div>
                    <div class="text-muted small d-flex justify-content-between mt-1">
                        <span>${escapeHtml(providerName(appointment))} · ${escapeHtml(appointment.service?.name || '')}</span>
                        <span>${timerLabel}</span>
                    </div>
                    <div class="progress mt-2" style="height:5px">
                        <div class="progress-bar ${overdue ? 'bg-warning' : ''}" style="width:${pct}%"></div>
                    </div>
                </div>
            `;
        });

        $list.html(rows.join(''));
    }

    function renderOverdueAttention(appointments) {
        const overdue = appointments.filter((a) => App.Utils.SessionStatus.compute(a).status === 'overdue');
        const $target = $('#dash-attention-overdue');

        if (!overdue.length) {
            $target.empty();
            return;
        }

        $('#dash-attention-empty').hide();

        $target.html(`
            <a href="${App.Utils.Url.siteUrl('calendar')}" class="list-group-item list-group-item-action d-flex align-items-center gap-3 py-3">
                <i class="fas fa-circle text-warning" style="font-size:8px"></i>
                <div class="flex-grow-1">
                    <div class="fw-bold small">${overdue.length} seans gecikmiş</div>
                    <div class="text-muted small">Planlanan süresini aşan aktif seanslar</div>
                </div>
                <span class="text-primary small fw-bold">Görüntüle →</span>
            </a>
        `);
    }

    function post(action, data) {
        const dfd = $.Deferred();
        const csrfToken = (typeof vars === 'function' ? vars('csrf_token') : null) || $('[name="csrf_token"]').val() || '';
        const params = new URLSearchParams(Object.assign({ csrf_token: csrfToken }, data || {}));
        fetch(action, {
            method: 'POST',
            headers: {
                'X-Requested-With': 'XMLHttpRequest',
                'Content-Type': 'application/x-www-form-urlencoded',
            },
            body: params.toString(),
        })
            .then((response) => response.json())
            .then((json) => dfd.resolve(json))
            .catch((error) => dfd.reject(error));
        return dfd.promise();
    }

    function onAiActionClick(actionUrl, successMsg) {
        return function (e) {
            e.preventDefault();
            const $btn = $(this);
            const $item = $btn.closest('.dash-ai-item');
            const id = $item.data('id');

            $btn.prop('disabled', true).text('İşleniyor...');

            post(actionUrl, { id: id })
                .done((response) => {
                    if (response.success) {
                        $item.slideUp(200, function () {
                            $item.remove();
                            const remaining = $('.dash-ai-item').length;
                            $('#dash-ai-count').text(remaining);
                            if (remaining === 0) {
                                $('#dash-attention .bg-light-subtle').slideUp(150, function () { $(this).remove(); });
                            }
                        });
                        if (window.App?.Layouts?.Backend?.displayNotification) {
                            App.Layouts.Backend.displayNotification(successMsg, 'success');
                        }
                        poll();
                    } else {
                        if (window.App?.Layouts?.Backend?.displayNotification) {
                            App.Layouts.Backend.displayNotification(response.message || 'İşlem başarısız.', 'error');
                        }
                        $btn.prop('disabled', false).html('<i class="fas fa-check me-1"></i> Onayla & Takvime İşle');
                    }
                })
                .fail(() => {
                    if (window.App?.Layouts?.Backend?.displayNotification) {
                        App.Layouts.Backend.displayNotification('İstek başarısız oldu.', 'error');
                    }
                    $btn.prop('disabled', false).html('<i class="fas fa-check me-1"></i> Onayla & Takvime İşle');
                });
        };
    }

    function poll() {
        App.Http.Calendar.getActiveSessions().done((response) => {
            if (!response.success) {
                return;
            }

            App.Utils.SessionStatus.syncServerTime(response.server_time);

            renderLiveSessions(response.appointments || []);
            renderOverdueAttention(response.appointments || []);
        });
    }

    $(function () {
        if (!$('#dashboard-page').length) {
            return;
        }

        const routes = (typeof vars === 'function' ? vars('routes') : null) || {};
        const approveUrl = routes.ai_approve || (App.Utils.Url.siteUrl ? App.Utils.Url.siteUrl('ai_agent/approve') : '/index.php/ai_agent/approve');
        const rejectUrl = routes.ai_reject || (App.Utils.Url.siteUrl ? App.Utils.Url.siteUrl('ai_agent/reject') : '/index.php/ai_agent/reject');

        $(document).on('click', '.dash-ai-approve', onAiActionClick(approveUrl, 'AI randevu talebi başarıyla onaylandı ve takvime işlendi!'));
        $(document).on('click', '.dash-ai-reject', onAiActionClick(rejectUrl, 'AI randevu talebi reddedildi.'));

        poll();
        setInterval(poll, POLL_INTERVAL_MS);
    });
})();
